begin;
create extension if not exists pgcrypto;
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,organization_id uuid references public.organizations(id),full_name text not null,username text not null unique,status text not null default 'active' check(status in('active','inactive','blocked')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.roles(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,code text not null,name text not null,unique(organization_id,code));
create table public.permissions(code text primary key,description text not null);
create table public.role_permissions(role_id uuid references public.roles(id) on delete cascade,permission_code text references public.permissions(code) on delete cascade,primary key(role_id,permission_code));
create table public.user_roles(user_id uuid references public.profiles(id) on delete cascade,role_id uuid references public.roles(id) on delete cascade,primary key(user_id,role_id));
create table public.audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id),actor_id uuid references public.profiles(id),action text not null,entity_type text not null,entity_id text,old_data jsonb,new_data jsonb,reason text,created_at timestamptz not null default now());
insert into public.permissions values ('users.manage','Administrar usuarios'),('roles.manage','Administrar roles'),('subscribers.read','Consultar abonados'),('subscribers.create','Crear abonados'),('subscribers.update','Modificar abonados y pegues'),('audit.read','Consultar auditoría'),('settings.manage','Administrar configuración'),('backups.manage','Administrar respaldos');
create or replace function public.current_organization_id() returns uuid language sql stable security definer set search_path=public as $$select organization_id from profiles where id=auth.uid() and status='active'$$;
create or replace function public.has_permission(p_code text) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from user_roles ur join role_permissions rp on rp.role_id=ur.role_id join profiles p on p.id=ur.user_id where ur.user_id=auth.uid() and p.status='active' and rp.permission_code=p_code)$$;
create or replace function public.get_my_authorization() returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('profile',to_jsonb(p),'permissions',coalesce((select jsonb_agg(distinct rp.permission_code) from user_roles ur join role_permissions rp on rp.role_id=ur.role_id where ur.user_id=p.id),'[]'::jsonb)) from profiles p where p.id=auth.uid()$$;
create or replace function public.write_audit_event(p_action text,p_entity_type text,p_entity_id text default null,p_old jsonb default null,p_new jsonb default null,p_reason text default null) returns void language plpgsql security definer set search_path=public as $$begin insert into audit_events(organization_id,actor_id,action,entity_type,entity_id,old_data,new_data,reason) values(current_organization_id(),auth.uid(),p_action,p_entity_type,p_entity_id,p_old,p_new,p_reason); end$$;
create or replace function public.bootstrap_organization(p_name text,p_full_name text,p_username text) returns uuid language plpgsql security definer set search_path=public as $$declare org uuid; r uuid;begin if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;if exists(select 1 from organizations) or (select count(*) from auth.users)>1 then raise exception 'BOOTSTRAP_DENIED';end if;insert into organizations(name) values(trim(p_name)) returning id into org;insert into profiles(id,organization_id,full_name,username) values(auth.uid(),org,trim(p_full_name),lower(trim(p_username)));insert into roles(organization_id,code,name) values(org,'superadmin','Administrador principal') returning id into r;insert into role_permissions select r,code from permissions;insert into user_roles values(auth.uid(),r);perform write_audit_event('bootstrap','organization',org::text,null,jsonb_build_object('name',p_name),'Inicialización segura');return org;end$$;
alter table organizations enable row level security;alter table profiles enable row level security;alter table roles enable row level security;alter table role_permissions enable row level security;alter table user_roles enable row level security;alter table audit_events enable row level security;
create policy org_read on organizations for select using(id=current_organization_id());
create policy profile_read on profiles for select using(organization_id=current_organization_id());create policy profile_manage on profiles for all using(organization_id=current_organization_id() and has_permission('users.manage')) with check(organization_id=current_organization_id() and has_permission('users.manage'));
create policy roles_read on roles for select using(organization_id=current_organization_id());create policy roles_manage on roles for all using(organization_id=current_organization_id() and has_permission('roles.manage')) with check(organization_id=current_organization_id() and has_permission('roles.manage'));
create policy role_permissions_read on role_permissions for select using(exists(select 1 from roles r where r.id=role_id and r.organization_id=current_organization_id()));
create policy user_roles_read on user_roles for select using(exists(select 1 from profiles p where p.id=user_id and p.organization_id=current_organization_id()));
create policy audit_read on audit_events for select using(organization_id=current_organization_id() and has_permission('audit.read'));
revoke update,delete on audit_events from authenticated;revoke all on function bootstrap_organization(text,text,text) from public;grant execute on function bootstrap_organization(text,text,text) to authenticated;
commit;
